// Simple hash function (djb2 algorithm)
function hashString(str) {
  let hash = 5381;
  for (let i = 0; i < str.length; i++) {
    hash = ((hash << 5) + hash) + str.charCodeAt(i);
    hash = hash & hash;
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function truncate(str, maxLength = 5000) {
  if (!str) return '';
  str = String(str);
  if (str.length <= maxLength) return str;
  return str.substring(0, maxLength - 3) + '...';
}

function stripHtml(html) {
  if (!html) return '';
  return String(html)
    .replace(/<[^>]*>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

// Virality scoring function
function calculateViralityScore(title, description, source, pubDate) {
  let score = 0;
  const titleLower = (title || '').toLowerCase();
  const descLower = (description || '').toLowerCase();
  const combined = titleLower + ' ' + descLower;

  // Title keywords (max +40)
  const viralKeywords = {
    'breaking': 10, 'exclusive': 10, 'revealed': 8, 'leaked': 8,
    'urgent': 7, 'warning': 7, 'finally': 6, 'secret': 6,
    'why': 5, 'how': 5, 'what': 4, '?': 3
  };
  for (const [keyword, points] of Object.entries(viralKeywords)) {
    if (titleLower.includes(keyword)) score += points;
  }
  // Numbers in title boost engagement
  if (/\d+/.test(title)) score += 5;
  // Cap title keywords at 40
  score = Math.min(score, 40);

  // Source weight (max +25)
  const sourceWeights = {
    'verge': 25, 'theverge': 25,
    'lifehacker': 20,
    'calnewport': 15
  };
  const sourceLower = (source || '').toLowerCase();
  for (const [src, points] of Object.entries(sourceWeights)) {
    if (sourceLower.includes(src)) {
      score += points;
      break;
    }
  }

  // Topic relevance for PDFLab (max +25)
  const relevantKeywords = {
    'pdf': 10, 'document': 8, 'adobe': 7, 'acrobat': 7,
    'productivity': 6, 'focus': 5, 'distraction': 5,
    'privacy': 5, 'data': 4, 'subscription': 4,
    'study': 4, 'notes': 4, 'student': 4,
    'slow': 3, 'lag': 3, 'bloat': 3
  };
  let topicScore = 0;
  for (const [keyword, points] of Object.entries(relevantKeywords)) {
    if (combined.includes(keyword)) topicScore += points;
  }
  score += Math.min(topicScore, 25);

  // Recency bonus (max +10)
  if (pubDate) {
    try {
      const ageHours = (Date.now() - new Date(pubDate).getTime()) / (1000 * 60 * 60);
      if (ageHours < 6) score += 10;
      else if (ageHours < 12) score += 8;
      else if (ageHours < 24) score += 6;
      else if (ageHours < 48) score += 4;
      else if (ageHours < 72) score += 2;
    } catch (e) {}
  }

  return Math.min(score, 100);
}

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let url = data.link || data.url || data.guid || '';
  if (!url) continue;

  // Clean URL of tracking params
  try {
    const urlObj = new URL(url);
    ['utm_source', 'utm_medium', 'utm_campaign', 'utm_content', 'utm_term',
     'ref', 'source', 'fbclid', 'gclid', 'mc_cid', 'mc_eid'].forEach(param => {
      urlObj.searchParams.delete(param);
    });
    url = urlObj.toString().replace(/\/$/, '');
  } catch (e) {}

  // Generate hash
  const urlHash = hashString(url) + hashString(url.split('').reverse().join('')) + url.length.toString(16);

  // Detect source
  let source = 'unknown';
  try {
    const hostname = new URL(url).hostname.toLowerCase();
    if (hostname.includes('lifehacker')) source = 'lifehacker';
    else if (hostname.includes('theverge') || hostname.includes('verge')) source = 'verge';
    else if (hostname.includes('calnewport')) source = 'calnewport';
    else source = hostname.replace('www.', '').split('.')[0];
  } catch (e) {}

  // Parse date
  let pubDate = data.pubDate || data.published || data.date || data.isoDate || null;
  let pubTimestamp = null;
  if (pubDate) {
    try { pubTimestamp = new Date(pubDate).getTime(); } catch (e) {}
  }

  // Clean text fields
  let description = stripHtml(data.description || data.summary || data.content || '');
  description = truncate(description, 2000);
  let title = truncate(data.title || '', 500);

  // Calculate virality score
  const virality_score = calculateViralityScore(title, description, source, pubDate);

  results.push({
    json: {
      urlHash,
      url: truncate(url, 2000),
      title,
      description,
      source,
      pubDate,
      pubTimestamp,
      virality_score
    }
  });
}

return results;

