const body = $input.first().json.body;
let payload;

try {
  if (typeof body.payload === 'string') {
    payload = JSON.parse(body.payload);
  } else {
    payload = body.payload || body;
  }
} catch (e) {
  payload = body;
}

// Handle Modal Submission (Edit)
if (payload.type === 'view_submission') {
  const values = payload.view.state.values;
  let newText = '';
  for (const blockId in values) {
    for (const actionId in values[blockId]) {
      if (values[blockId][actionId].value) {
         newText = values[blockId][actionId].value;
      }
    }
  }

  const metadata = JSON.parse(payload.view.private_metadata || '{}');

  return [{
    json: {
      action: 'submit_edit',
      platform: metadata.platform,
      postText: newText,
      imageUrl: metadata.imageUrl,
      user: payload.user.name,
      responseUrl: null
    }
  }];
}

// Handle Buttons - decode base64 payload
const action = payload.actions?.[0] || {};
const actionId = action.action_id || '';
const actionValue = action.value || '';

let platform = '';
let postText = '';
let imageUrl = '';

// Decode base64 encoded button value
if (actionValue && actionValue !== 'reject') {
  try {
    const decoded = JSON.parse(Buffer.from(actionValue, 'base64').toString('utf-8'));
    platform = decoded.platform || '';
    postText = decoded.postText || '';
    imageUrl = decoded.imageUrl || '';
  } catch (e) {
    // Fallback for legacy pipe-delimited format
    if (actionValue.includes('|')) {
      const parts = actionValue.split('|');
      if (parts.length >= 3) {
        platform = parts[0];
        postText = parts[1];
        imageUrl = parts[2];
      }
    }
  }
}

return [{
  json: {
    action: actionId,
    trigger_id: payload.trigger_id,
    platform,
    postText,
    imageUrl,
    user: payload.user?.name || 'unknown',
    responseUrl: payload.response_url
  }
}];

